// Shared asynchronous dialogs. Never interpolate caller text as HTML.
let tail=Promise.resolve(),serial=0;
const sheet=document.createElement('link');sheet.rel='stylesheet';sheet.href=new URL('./site-dialogs.css',import.meta.url);const styled=new Promise(resolve=>{sheet.onload=sheet.onerror=resolve});document.head.append(sheet);
const node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
function labels(message){const m=message.toLowerCase();if(m.startsWith('permanently delete uid'))return {title:'Delete UID listing?',action:'Delete listing',danger:true};if(m.startsWith('delete this formation'))return {title:'Delete formation?',action:'Delete formation',danger:true};if(m.startsWith('delete this tierlist'))return {title:'Delete tierlist?',action:'Delete tierlist',danger:true};if(m.startsWith('unpublish'))return {title:'Unpublish?',action:'Unpublish'};if(m.startsWith('publish'))return {title:'Publish formation?',action:'Publish'};if(m.startsWith('clear'))return {title:'Clear formation?',action:'Clear board'};if(m.includes('board mode'))return {title:'Change board mode?',action:'Change mode'};if(m.includes('game mode'))return {title:'Change game mode?',action:'Change mode'};if(m.startsWith('start a new tierlist'))return {title:'Start a new tierlist?',action:'Reset tierlist'};if(m.startsWith('discard'))return {title:'Discard unsaved changes?',action:m.includes('reload')?'Discard and reload':'Discard changes'};if(m.startsWith('restore and publish'))return {title:'Restore original data?',action:'Restore and publish'};if(m.startsWith('replace unsaved'))return {title:'Replace unsaved changes?',action:'Replace changes'};return {title:'Confirm action',action:'Continue'}}
function show(kind,message,options={}){const opener=document.activeElement;const run=async()=>{await styled;return new Promise(resolve=>{
 const info={...labels(message),...options},id='site-dialog-'+(++serial),dialog=node('dialog',undefined,'site-dialog site-modal'),head=node('div',undefined,'modal-head'),title=node('h3',info.title),close=node('button','×','standard-modal-close'),body=node('div',undefined,'modal-body'),description=node('p',message),form=node('form'),actions=node('div',undefined,'modal-actions');title.id=id+'-title';description.id=id+'-description';dialog.setAttribute('aria-labelledby',title.id);dialog.setAttribute('aria-describedby',description.id);close.type='button';close.setAttribute('aria-label','Close dialog');head.append(title,close);body.append(description);
 let input=null,result=kind==='confirm'?false:null,settled=false;
 if(kind==='prompt'){const label=node('label',info.label||'Value','dialog-field');input=node('input');input.type='text';input.value=info.value??'';input.placeholder=info.placeholder||'';input.maxLength=info.maxLength||500;label.append(input);body.append(label)}
 const cancel=node('button',info.cancelLabel||'Cancel','dialog-button secondary'),accept=node('button',kind==='alert'?(info.action||'Got it'):(info.action||'Save'),'dialog-button'+(info.danger?' danger':''));cancel.type='button';accept.type='submit';if(kind!=='alert')actions.append(cancel);actions.append(accept);form.append(body,actions);dialog.append(head,form);
 const finish=()=>{if(settled)return;settled=true;dialog.remove();if(opener?.isConnected)opener.focus({preventScroll:true});resolve(result)};
 dialog.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const targets=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled])')],first=targets[0],last=targets.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
 close.onclick=cancel.onclick=()=>dialog.close();dialog.addEventListener('close',finish,{once:true});dialog.addEventListener('cancel',()=>{result=kind==='confirm'?false:null});form.onsubmit=e=>{e.preventDefault();result=kind==='prompt'?input.value:true;dialog.close()};document.body.append(dialog);dialog.showModal();(input|| (kind==='alert'?accept:cancel)).focus();input?.select();
 })};const pending=tail.then(run,run);tail=pending.catch(()=>{});return pending}
export const confirmDialog=(message,options)=>show('confirm',message,options);
export const promptDialog=(message,options)=>show('prompt',message,{title:'Enter a value',action:'Save',...options});
export const alertDialog=(message,options)=>show('alert',message,{title:'Information',action:'Got it',...options});

let toast=null,toastTimer;
export function notify(message){clearTimeout(toastTimer);toast?.remove();toast=node('div',undefined,'site-toast');toast.setAttribute('role','status');const text=node('span',message),close=node('button','×');close.type='button';close.setAttribute('aria-label','Dismiss notification');const dismiss=()=>{clearTimeout(toastTimer);toast?.remove();toast=null};close.onclick=dismiss;toast.append(text,close);document.body.append(toast);const expire=()=>{clearTimeout(toastTimer);toastTimer=setTimeout(dismiss,6000)};toast.onpointerenter=toast.onfocusin=()=>clearTimeout(toastTimer);toast.onpointerleave=expire;toast.onfocusout=expire;expire()}
